<template>
  <div class="analytics-page" :aria-busy="pending">
    <header class="report-heading"><div><span class="eyebrow">PERFORMANCE REPORT</span><h1>Store analytics</h1><p>A closer look at sales, order activity and product performance.</p></div><div class="period-control"><CalendarDays :size="18" /><AppSelect v-model="days" :options="[7,30,90].map(id=>({id,name:`Last ${id} days`}))" aria-label="Analytics period" :allow-empty="false" :searchable="false" /></div></header>
    <div v-if="error" class="tw:alert report-error" role="alert"><AlertCircle :size="20" /><span>We couldn't load analytics. Please try again.</span><button class="tw:btn tw:btn-sm" @click="refresh">Retry</button></div>
    <div v-else-if="pending && !report" class="tw:skeleton report-loading" aria-label="Loading analytics" />
    <template v-else-if="report?.permissions.orders">
      <p v-if="pending" class="refresh-note" role="status">Updating report...</p>
      <section class="revenue-report">
        <div class="revenue-summary" data-metric="revenue"><span class="report-icon"><ChartNoAxesCombined :size="23" /></span><h2>Paid revenue</h2><strong class="metric-value">{{ money(revenue) }}</strong><span class="tw:badge revenue-change" :class="{negative:change<0}">{{ change === null ? 'New revenue' : `${change>0?'+':''}${change}%` }}</span><small>vs. previous {{ days }} days</small><p>Paid, non-cancelled orders</p><div class="date-range">{{ dateLabel(report.period.start) }} – {{ dateLabel(report.period.end) }} · {{ report.period.timezone }}</div></div>
        <div class="revenue-visual"><div class="section-heading"><div><h2>Revenue trend</h2><p>Daily revenue across the selected period</p></div><span class="tw:badge currency-pill">{{ report.period.currency }}</span></div><div class="revenue-chart"><ClientOnly><Line :data="revenueData" :options="revenueOptions" role="img" aria-label="Daily paid revenue" /></ClientOnly></div></div>
      </section>
      <div class="insight-grid">
        <article class="tw:card insight-card" data-insight="aov"><span class="insight-icon"><Wallet :size="21" /></span><div><h2>Average order value</h2><strong>{{ money(report.sales.average_order_value) }}</strong><p>Per paid, non-cancelled order</p></div></article>
        <article class="tw:card insight-card" data-insight="paid-rate"><span class="insight-icon green"><BadgeCheck :size="21" /></span><div><h2>Paid-order rate</h2><strong>{{ paidRate.toFixed(1) }}<small>%</small></strong><p>{{ count(report.sales.paid_orders) }} of {{ count(orderTotal) }} orders are paid and not cancelled</p></div></article>
        <article class="tw:card insight-card" data-insight="daily-revenue"><span class="insight-icon gold"><CalendarDays :size="21" /></span><div><h2>Average daily revenue</h2><strong>{{ money(revenue/report.period.days) }}</strong><p>Across {{ report.period.days }} calendar days</p></div></article>
      </div>
      <div class="activity-grid">
        <section class="tw:card report-panel"><div class="section-heading"><div><h2><ShoppingCart :size="18" />Order activity</h2><p>Daily order volume, including all statuses</p></div><span class="activity-total">{{ count(orderTotal) }} <small>orders</small></span></div><div class="activity-chart"><ClientOnly><Bar :data="orderData" :options="orderOptions" role="img" aria-label="Daily order volume" /></ClientOnly></div></section>
        <section class="tw:card report-panel status-report"><div class="section-heading"><div><h2>Order breakdown</h2><p>Share of orders by status</p></div></div><ul><li v-for="status in statuses" :key="status.status"><div><span class="status-dot" :style="{background:status.color}" /><span>{{ status.label }}</span><strong>{{ count(status.count) }} <small>{{ percent(status.count).toFixed(1) }}%</small></strong></div><progress class="tw:progress status-progress" :value="status.count" :max="orderTotal || 1" :style="{color:status.color}" :aria-label="`${status.label} share`" /></li></ul><p v-if="!orderTotal" class="empty-status">No orders in this period.</p></section>
      </div>
      <section v-if="report.permissions.products" class="tw:card report-panel product-report"><div class="section-heading"><div><h2><Trophy :size="19" />Product performance</h2><p>Top five products by units sold in paid, non-cancelled orders.</p></div><NuxtLink to="/admin/products" class="report-link">Manage products <ArrowUpRight :size="16" /></NuxtLink></div><div v-if="report.top_products?.length" class="performance-scroll"><table class="tw:table performance-table"><thead><tr><th>Rank</th><th>Product</th><th>Units sold</th><th>Revenue</th><th>Share of paid revenue</th></tr></thead><tbody><tr v-for="(product,index) in report.top_products" :key="`${product.id}-${index}`"><td><span class="rank">{{ String(index+1).padStart(2,'0') }}</span></td><td><div class="product-cell"><img :src="product.image || placeholder" :alt="product.name" width="42" height="42" @error="imageFallback" /><NuxtLink v-if="product.id && admin.can('products.edit')" :to="`/admin/products/${product.id}/edit`">{{ product.name }}</NuxtLink><span v-else>{{ product.name }}</span></div></td><td>{{ count(product.quantity) }}</td><td class="revenue-cell">{{ money(product.revenue) }}</td><td><div class="contribution"><progress class="tw:progress" :value="product.revenue" :max="revenue || 1" :aria-label="`${product.name} revenue share`" /><span>{{ revenue ? (product.revenue/revenue*100).toFixed(1) : '0.0' }}%</span></div></td></tr></tbody></table></div><div v-else class="report-empty"><PackageOpen :size="30" /><h3>No product sales to report yet</h3><p>Product performance will appear here as paid orders come in.</p></div></section>
      <p class="report-note">Revenue reflects order totals recorded in the store. It is not a profit calculation.</p>
    </template>
    <div v-else class="tw:card report-panel report-empty"><ChartNoAxesCombined :size="30" /><h2>Sales reporting is unavailable for your role</h2><p>Ask an administrator for access to order reports.</p></div>
  </div>
</template>
<script setup>
import { AlertCircle, ArrowUpRight, BadgeCheck, CalendarDays, ChartNoAxesCombined, PackageOpen, ShoppingCart, Trophy, Wallet } from 'lucide-vue-next'
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, BarElement, Tooltip, Filler } from 'chart.js'
import { Line, Bar } from 'vue-chartjs'
ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, BarElement, Tooltip, Filler)
ChartJS.defaults.font.family='Poppins, sans-serif'
definePageMeta({layout:'admin'})
useHead({title:'Store Analytics - FGX MART Admin'})
const admin=useAdminAuth()
const days=ref(30)
const {data:response,pending,error,refresh}=await useAsyncData('admin-analytics',()=>$adminApi('/dashboard',{query:{days:days.value}}),{watch:[days]})
const report=computed(()=>response.value?.data?.metrics ? response.value.data : null)
const revenue=computed(()=>Number(report.value?.metrics.revenue?.value || 0))
const change=computed(()=>report.value?.metrics.revenue?.change_percent ?? null)
const orderTotal=computed(()=>Number(report.value?.metrics.orders?.value || 0))
const paidRate=computed(()=>orderTotal.value ? Number(report.value?.sales?.paid_orders || 0)/orderTotal.value*100 : 0)
const money=value=>new Intl.NumberFormat('en-US',{style:'currency',currency:report.value?.period.currency || 'USD'}).format(Number(value || 0))
const count=value=>new Intl.NumberFormat('en-US').format(Number(value || 0))
const dateLabel=value=>new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',timeZone:'UTC'}).format(new Date(`${value}T00:00:00Z`))
const definitions={delivered:['Delivered','#78a94b'],processing:['Processing','#8756c5'],confirmed:['Confirmed','#6999cf'],shipped:['Shipped','#4a9e96'],pending:['Pending','#d6aa40'],cancelled:['Cancelled','#d77a92']}
const statuses=computed(()=>(report.value?.statuses || []).map(status=>({...status,label:definitions[status.status]?.[0] || status.status,color:definitions[status.status]?.[1] || '#9b8ba9'})))
const percent=value=>orderTotal.value ? value/orderTotal.value*100 : 0
const series=computed(()=>report.value?.sales?.series || [])
const revenueData=computed(()=>({labels:series.value.map(day=>dateLabel(day.date)),datasets:[{label:'Paid revenue',data:series.value.map(day=>day.revenue),borderColor:'#8855c4',backgroundColor:'#9f79d31c',fill:true,tension:.25,borderWidth:2.5,pointRadius:days.value===7?3:0,pointHoverRadius:5}]}))
const orderData=computed(()=>({labels:series.value.map(day=>dateLabel(day.date)),datasets:[{label:'Orders',data:series.value.map(day=>day.orders),backgroundColor:'#a78bca',hoverBackgroundColor:'#7745ac',borderRadius:4,maxBarThickness:28}]}))
const chartOptions={responsive:true,maintainAspectRatio:false,animation:false,interaction:{mode:'index',intersect:false},plugins:{legend:{display:false},tooltip:{backgroundColor:'#382251',padding:10}},scales:{x:{grid:{display:false},border:{display:false},ticks:{maxTicksLimit:7,maxRotation:0,color:'#9989a6',font:{size:10}}},y:{beginAtZero:true,border:{display:false},grid:{color:'#f0eaf5'},ticks:{maxTicksLimit:5,color:'#9989a6',font:{size:10}}}}}
const revenueOptions={...chartOptions,plugins:{...chartOptions.plugins,tooltip:{...chartOptions.plugins.tooltip,callbacks:{label:context=>money(context.parsed.y)}}}}
const orderOptions={...chartOptions,scales:{...chartOptions.scales,y:{...chartOptions.scales.y,ticks:{...chartOptions.scales.y.ticks,precision:0}}}}
const placeholder='/assets/images/home/product-placeholder.webp'
const imageFallback=event=>{if(!event.target.dataset.fallback){event.target.dataset.fallback='true';event.target.src=placeholder}}
</script>
