;color:#ad9bb9;margin:20px 0 0}.report-link{display:flex;align-items:center;gap:6px;font-size:11px;color:#8651b1;text-decoration:none}.performance-scroll{overflow:auto}.performance-table{width:100%;min-width:640px;border-collapse:collapse}.performance-table th{font-size:10px;font-weight:500;color:#a18eaf;background:#faf7fd;padding:13px 12px;text-align:left;white-space:nowrap}.performance-table td{font-size:12px;color:#867092;padding:15px 12px;border-bottom:1px solid #f3edf7}.performance-table tr:last-child td{border-bottom:0}.rank{font-size:12px;color:#b6a5c2}.product-cell{display:flex;align-items:center;gap:14px;max-width:430px;min-width:200px;color:#634974;font-weight:550}.product-cell img{width:42px;height:42px;object-fit:contain;background:#faf7fd;border-radius:7px;flex-shrink:0}.product-cell a{color:inherit}.revenue-cell{font-weight:650;white-space:nowrap}.contribution{display:flex;align-items:center;gap:12px}.contribution progress{height:5px;width:110px;color:#9c78c7;background:#f4eef9}.contribution span{font-size:10px;min-width:40px}.report-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:12px;min-height:180px;color:#a18eaf}.report-empty h3,.report-empty h2{font-size:15px;margin:0;color:#725a85}.report-empty p{font-size:12px;margin:0}.report-note{font-size:10px;color:#b09ebc;margin:0}.report-error{padding:20px;background:#fff1f5;color:#ac526e;border:1px solid #f0d4de}.report-loading{min-height:360px;background:#eee7f5;border-radius:18px}.refresh-note{font-size:11px;color:#a18eaf;margin:0}
