@media(max-width:700px){.analytics-page{gap:18px}.report-heading{align-items:flex-start;flex-direction:column;gap:18px}.report-heading h1{font-size:25px}.report-heading p{font-size:12px;line-height:1.7}.revenue-report{grid-template-columns:1fr}.revenue-summary{padding:24px}.report-icon{margin-bottom:15px}.revenue-summary p{margin-top:17px}.revenue-visual{padding:20px 16px}.revenue-chart{height:220px}.insight-grid{grid-template-columns:1fr;gap:12px}.insight-card{padding:20px}.insight-card strong{font-size:26px}.report-panel{padding:20px 16px}.section-heading{gap:12px;margin-bottom:20px}.section-heading h2{font-size:16px}.activity-chart{height:220px}.report-note{line-height:1.8}}
